'use client'

import { useRouter } from 'next/navigation'

interface TransitionLinkProps {
  href: string
  children: React.ReactNode
  className?: string
  'data-transition-type'?: string
  [key: string]: unknown
}

export function TransitionLink({ href, children, className, 'data-transition-type': transitionType, ...props }: TransitionLinkProps) {
  const router = useRouter()

  const handleClick = (e: React.MouseEvent) => {
    e.preventDefault()

    const direction = transitionType || (href.startsWith('/product') ? 'forward' : 'back')

    if (document.startViewTransition) {
      document.documentElement.dataset.navigationDirection = direction
      document.startViewTransition(() => {
        router.push(href)
      })
    } else {
      router.push(href)
    }
  }

  return (
    <a href={href} onClick={handleClick} className={className} {...props}>
      {children}
    </a>
  )
}

