import './globals.css'
import { ViewTransitionProvider } from './ViewTransitionProvider'

export const metadata: Metadata = {
  title: 'Product Gallery',
  description: 'A simple product gallery',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <head>
        <script
          dangerouslySetInnerHTML={{
            __html: `
              (function() {
                var motion = window.matchMedia('(prefers-reduced-motion: reduce)');
                document.documentElement.dataset.reduceMotion = motion.matches ? 'true' : 'false';
                motion.addEventListener('change', function() {
                  document.documentElement.dataset.reduceMotion = motion.matches ? 'true' : 'false';
                });
              })();
            `,
          }}
        />
      </head>
      <body>
        <ViewTransitionProvider>{children}</ViewTransitionProvider>
      </body>
    </html>
  )
}

